mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM ast_device_assembly
    WHERE tenant_id = #{query.tenantId}
      AND source_system = #{query.sourceSystem}
      AND source_key = #{query.sourceKey}
      AND deleted = b'0'
)

mapper.update:
UPDATE ast_device_assembly
SET effective_to = #{effectiveAt},
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND parent_device_sn = #{parentDeviceSn}
  AND position_code = #{positionCode}
  AND effective_to IS NULL
  AND deleted = b'0'
